files.src/appointments/policy.py:
"""Decision rules for the clinic appointment hold, not transport or reporting."""

def can_release(record: dict, actor: str) -> bool:
    """Validate the clinician requirement and lifecycle state."""
    gate = record.get("clinician")
    return bool(actor and gate and record.get("status") == "pending")


def extension_deadline(record: dict, hours: int) -> int:
    """Clamp a clinic appointment hold extension to 24 hours after creation."""
    if hours < 0:
        raise ValueError("Extension must not be negative")
    current = int(record["deadline"])
    maximum = int(record["created"]) + 24
    return min(current + hours, maximum)


def may_revoke(record: dict, actor: str) -> bool:
    """Require the same owner for active clinic appointment hold withdrawal."""
    active = record.get("status") in {"pending", "released"}
    return bool(active and actor and record.get("owner") == actor)

