"""Current clinic appointment hold lifecycle implementation."""

from .policy import can_release, extension_deadline, may_revoke
from .store import load_record, save_record, remove_record


def release(records: dict, key: str, actor: str) -> dict:
    """Release this clinic appointment hold after its domain gate."""
    record = load_record(records, key)
    if not can_release(record, actor):
        raise ValueError("A clinic hold needs its assigned clinician before it can be released.")
    result = {**record, "status": "released", "actor": actor}
    return save_record(records, key, result)


def extend(records: dict, key: str, hours: int) -> dict:
    """Extend the clinic appointment hold while preserving its maximum lifetime."""
    record = load_record(records, key)
    deadline = extension_deadline(record, hours)
    result = {**record, "deadline": deadline}
    return save_record(records, key, result)


def revoke(records: dict, key: str, actor: str) -> dict:
    """Withdraw the active clinic appointment hold; never remove a completed record."""
    record = load_record(records, key)
    if not may_revoke(record, actor):
        raise ValueError("Completed or differently owned record cannot be revoked")
    return remove_record(records, key)

files.src/appointments/store.py:
"""In-memory clinic appointment hold records used by the current domain service."""

def load_record(records: dict, key: str) -> dict:
    """Read one record and fail clearly when it does not exist."""
    if key not in records:
        raise KeyError("Record does not exist: " + key)
    return dict(records[key])


def save_record(records: dict, key: str, value: dict) -> dict:
    """Write a detached record copy and return another detached copy."""
    records[key] = dict(value)
    return dict(records[key])


def remove_record(records: dict, key: str) -> dict:
    """Remove an existing record and expose the previous detached value."""
    previous = dict(records[key])
    del records[key]
    return previous

