"""In-memory laboratory specimen records used by the current domain service."""

def load_record(records: dict, key: str) -> dict:
    """Read one record and fail clearly when it does not exist."""
    if key not in records:
        raise KeyError("Record does not exist: " + key)
    return dict(records[key])


def save_record(records: dict, key: str, value: dict) -> dict:
    """Write a detached record copy and return another detached copy."""
    records[key] = dict(value)
    return dict(records[key])


def remove_record(records: dict, key: str) -> dict:
    """Remove an existing record and expose the previous detached value."""
    previous = dict(records[key])
    del records[key]
    return previous

