// Current clinic appointment hold lifecycle implementation.
import { canRelease, extensionDeadline, mayRevoke } from "./policy";
import { loadRecord, saveRecord, removeRecord } from "./store";
import type { RecordValue } from "./types";

export function release(records: Map<string, RecordValue>, key: string, actor: string): RecordValue {
  // Release this clinic appointment hold after its domain gate.
  const record = loadRecord(records, key);
  if (!canRelease(record, actor)) {
    throw new Error("A clinic hold needs its assigned clinician before it can be released.");
  }
  const result = { ...record, status: "released", actor };
  return saveRecord(records, key, result);
}

export function extend(records: Map<string, RecordValue>, key: string, hours: number): RecordValue {
  // Extend the clinic appointment hold while preserving its maximum lifetime.
  const record = loadRecord(records, key);
  const deadline = extensionDeadline(record, hours);
  const result = { ...record, deadline };
  return saveRecord(records, key, result);
}

export function revoke(records: Map<string, RecordValue>, key: string, actor: string): RecordValue {
  // Withdraw the active clinic appointment hold; never remove a completed record.
  const record = loadRecord(records, key);
  if (!mayRevoke(record, actor)) {
    throw new Error("Completed or differently owned record cannot be revoked");
  }
  return removeRecord(records, key);
}

