// Decision rules for the broadcast licence, not transport or reporting.
import type { RecordValue } from "./types";

export function canRelease(record: RecordValue, actor: string): boolean {
  // Validate the territory requirement and lifecycle state.
  const gate = record.territory;
  return Boolean(actor && gate && record.status === "pending");
}

export function extensionDeadline(record: RecordValue, hours: number): number {
  // Clamp a broadcast licence extension to 48 hours after creation.
  if (hours < 0) throw new Error("Extension must not be negative");
  const current = record.deadline;
  const maximum = record.created + 48;
  return Math.min(current + hours, maximum);
}

export function mayRevoke(record: RecordValue, actor: string): boolean {
  // Require the same owner for active broadcast licence withdrawal.
  const active = record.status === "pending" || record.status === "released";
  return Boolean(active && actor && record.owner === actor);
}

files.src/media/service.ts:
// Current broadcast licence lifecycle implementation.
import { canRelease, extensionDeadline, mayRevoke } from "./policy";
import { loadRecord, saveRecord, removeRecord } from "./store";
import type { RecordValue } from "./types";

export function release(records: Map<string, RecordValue>, key: string, actor: string): RecordValue {
  // Release this broadcast licence after its domain gate.
  const record = loadRecord(records, key);
  if (!canRelease(record, actor)) {
    throw new Error("A broadcast licence cannot be released outside its permitted territory.");
  }
  const result = { ...record, status: "released", actor };
  return saveRecord(records, key, result);
}

export function extend(records: Map<string, RecordValue>, key: string, hours: number): RecordValue {
  // Extend the broadcast licence while preserving its maximum lifetime.
  const record = loadRecord(records, key);
  const deadline = extensionDeadline(record, hours);
  const result = { ...record, deadline };
  return saveRecord(records, key, result);
}

export function revoke(records: Map<string, RecordValue>, key: string, actor: string): RecordValue {
  // Withdraw the active broadcast licence; never remove a completed record.
  const record = loadRecord(records, key);
  if (!mayRevoke(record, actor)) {
    throw new Error("Completed or differently owned record cannot be revoked");
  }
  return removeRecord(records, key);
}

