// In-memory broadcast licence records used by the current domain service.
import type { RecordValue } from "./types";

export function loadRecord(records: Map<string, RecordValue>, key: string): RecordValue {
  const value = records.get(key);
  if (!value) throw new Error("Record does not exist: " + key);
  return { ...value };
}

export function saveRecord(records: Map<string, RecordValue>, key: string, value: RecordValue): RecordValue {
  records.set(key, { ...value });
  return { ...value };
}

export function removeRecord(records: Map<string, RecordValue>, key: string): RecordValue {
  const previous = { ...records.get(key)! };
  records.delete(key);
  return previous;
}

